// Runs the page's inline script against a minimal DOM stand-in and exercises the Verdict control.
const fs = require("fs");
const html = fs.readFileSync(process.argv[2], "utf8");
const dataText = html.match(/id="round-data">([\s\S]*?)<\/script>/)[1];
const script = html.match(/<script nonce="[0-9a-f]+">([\s\S]*?)<\/script>/)[1];
const all = [];
function node(tag) {
  const n = { tag, children: [], handlers: {}, style: {}, attrs: {}, textContent: "", value: "",
    appendChild(c) { this.children.push(c); return c; },
    addEventListener(t, f) { this.handlers[t] = f; },
    setAttribute(k, v) { this.attrs[k] = v; }, focus() {}, select() {} };
  all.push(n); return n;
}
const root = node("main");
global.document = {
  createElement: node,
  createTextNode: (t) => { const n = node("#text"); n.textContent = t; return n; },
  getElementById: (id) => (id === "root" ? root : { textContent: dataText }),
};
global.navigator = {};
new Function(script)();
const text = (n) => n.textContent + n.children.map(text).join("");
const radios = all.filter((n) => n.tag === "input" && n.type === "radio");
const notes = all.filter((n) => n.tag === "input" && n.type === "text");
const out = all.find((n) => n.tag === "textarea");
const pick = (i, v) => { const r = radios.filter((x) => x.value === v)[i]; r.checked = true; r.handlers.change(); };
pick(0, "merge"); notes[0].value = "docs only,\n fine"; notes[0].handlers.input();
pick(1, "request changes");
console.log("nodes:", all.length, "| articles:", all.filter((n) => n.tag === "article").length,
  "| links:", all.filter((n) => n.tag === "a").map((a) => a.href + " rel=" + a.rel).join(", "));
console.log("page text length:", text(root).length);
console.log("--- verdict box ---\n" + out.value);
EOF
